#!/usr/bin/env node
// scripts/pg-harness/port-schema.mjs
// TG-09: translate the migrated D1 schema (sqlite_master dump) into Postgres
// DDL. D1 semantics are preserved, not "improved":
//   - INTEGER PK AUTOINCREMENT -> GENERATED BY DEFAULT AS IDENTITY (explicit
//     ids keep working, omitted ids auto-assign — exactly like SQLite).
//   - REFERENCES / FOREIGN KEY clauses are DROPPED: D1 never enforced them
//     (no foreign_keys pragma anywhere — orphans exist by design, #79), so
//     enforcing them in PG would change behavior.
//   - strftime()/CURRENT_TIMESTAMP defaults -> gft_now() (TEXT ISO, compat.sql).
//   - Ledger append-only triggers -> plpgsql equivalents.
// Anything unrecognized fails LOUD (list it, don't guess).
// Usage: node scripts/pg-harness/port-schema.mjs [dump.json] [out.sql]
// Dump: wrangler d1 execute ... --command "SELECT type,name,sql FROM
//   sqlite_master WHERE ..." (see TG-09 notes in the file header below).

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const dumpPath = process.argv[2] || 'C:\\tmp\\pg-schema-dump.json';
const outPath = process.argv[3] || join(here, 'schema.sql');

const dump = JSON.parse(readFileSync(dumpPath, 'utf8'));
const rows = Array.isArray(dump) ? dump[0].results : dump.results;

const LEDGER_GUARD = `-- Ledger append-only guards (ported from SQLite triggers).
CREATE OR REPLACE FUNCTION ledger_append_only() RETURNS trigger AS $$
BEGIN RAISE EXCEPTION 'LEDGER_APPEND_ONLY'; END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_ledger_no_update BEFORE UPDATE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION ledger_append_only();
CREATE TRIGGER trg_ledger_no_delete BEFORE DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION ledger_append_only();
`;

const fkPairs = []; // [childTable, childCol, parentTable, parentCol]

function portTable(name, sql) {
  let t = sql;
  t = t.replace(/INTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT/gi, 'INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY');
  // REFERENCES are KEPT and enforced: D1 enforces them (E2E #79 proves an
  // orphan insert is refused), so PG must too. Applied as deferred ALTERs after
  // all tables exist (creation order can't satisfy forward references).
  const refRe = /(\w+)(\s+TEXT[^,]*?)REFERENCES\s+([A-Za-z_]\w*)\s*\((\w+)\)((?:\s+ON\s+(?:DELETE|UPDATE)\s+\w+)*)/gi;
  t = t.replace(refRe, (full, col, rest, pt, pc, actions) => {
    fkPairs.push([name, col, pt, pc, actions || '']);
    return `${col}${rest}`;
  });
  t = t.replace(/DEFAULT\s*\(\s*strftime\([^)]*\)\s*\)/gi, 'DEFAULT gft_now()');
  t = t.replace(/DEFAULT\s+CURRENT_TIMESTAMP/gi, 'DEFAULT gft_now()');
  // Bare TIMESTAMP columns held TEXT in D1 (SQLite affinity) — keep TEXT so
  // every comparison keeps its meaning. (After the DEFAULT rewrites above.)
  t = t.replace(/\bTIMESTAMP\b/gi, 'TEXT');
  return t;
}

function fkAlterTable() {
  // Deferred FK enforcement (creation order can't satisfy forward references).
  if (fkPairs.length !== 31) throw new Error(`REFERENCES drift: want 31, got ${fkPairs.length}`);
  return fkPairs.map(([ct, cc, pt, pc, actions]) =>
    `ALTER TABLE ${ct} ADD FOREIGN KEY (${cc}) REFERENCES ${pt}(${pc})${actions};`).join('\n');
}

function fkAuditView() {
  // pragma_foreign_key_check as a view: one anti-join per declared REFERENCE.
  // Shape (tbl, row_id, parent) is harness-local; the endpoint only counts rows.
  const legs = fkPairs.map(([ct, cc, pt, pc]) =>
    `SELECT '${ct}' AS tbl, c.${cc} AS row_id, '${pt}' AS parent FROM ${ct} c LEFT JOIN ${pt} p ON p.${pc} = c.${cc} WHERE c.${cc} IS NOT NULL AND p.${pc} IS NULL`);
  return `-- pragma_foreign_key_check emulation (${fkPairs.length} declared REFERENCES).\nCREATE OR REPLACE VIEW pragma_foreign_key_check AS\n${legs.join('\nUNION ALL\n')};`;
}

const problems = [];
const tables = [];
const indexes = [];
const seenTriggers = [];
for (const r of rows) {
  // D1-internal tables (bindings metadata) have no PG meaning.
  if (r.name.startsWith('_cf_')) continue;
  if (r.type === 'table') tables.push(`-- table ${r.name}\n${portTable(r.name, r.sql)};`);
  else if (r.type === 'index') indexes.push(`-- index ${r.name}\n${r.sql};`);
  else if (r.type === 'trigger') seenTriggers.push(r.name);
  else problems.push(`unknown sqlite_master type: ${r.type} ${r.name}`);
}
if (seenTriggers.sort().join(',') !== 'trg_ledger_no_delete,trg_ledger_no_update') {
  problems.push(`unexpected trigger set: ${seenTriggers.join(',')}`);
}
const body = tables.join('\n\n') + '\n\n' + indexes.join('\n\n');
// REFERENCES must be fully extracted into deferred ALTERs (none left inline).
for (const bad of ['AUTOINCREMENT', 'REFERENCES', 'strftime', 'PRAGMA', 'VACUUM', 'WITHOUT ROWID', 'rowid', 'GLOB', 'OR REPLACE', 'OR IGNORE']) {
  if (new RegExp(bad, 'i').test(body)) problems.push(`leftover ${bad} in ported schema`);
}
if (problems.length) {
  console.error('PORT FAILURES:\n- ' + problems.join('\n- '));
  process.exit(1);
}

const compat = readFileSync(join(here, 'compat.sql'), 'utf8');
const header = `-- TG-09 ported schema: D1 sqlite_master -> Postgres. Regenerate with
--   node scripts/pg-harness/port-schema.mjs C:\\tmp\\pg-schema-dump.json
-- Tables: ${tables.length}, indexes: ${indexes.length}. Do not hand-edit.
`;
writeFileSync(outPath, header + '\n' + compat + '\n' + body + '\n\n-- deferred FK enforcement\n' + fkAlterTable() + '\n\n' + fkAuditView() + '\n\n' + LEDGER_GUARD);
console.log(`ported ${tables.length} tables, ${indexes.length} indexes -> ${outPath}`);
